    ('TOTAL RM', re.compile(r'\bTOTAL\s*RM\b')),
    ('TOTAL ROUNDED', re.compile(r'\bTOTAL\s+ROUNDED\b')),
    ('TOTAL SALES', re.compile(r'\bTOTAL\s+SALES\b')),
    ('TOTAL AMOUNT', re.compile(r'\bTOTAL\s+AMOUNT\b')),
    ('TOTAL DUE', re.compile(r'\bTOTAL\s+DUE\b')),
    ('AMOUNT DUE', re.compile(r'\bAMOUNT\s+DUE\b')),
    ('BALANCE DUE', re.compile(r'\bBALANCE\s+DUE\b')),
    ('NETT TOTAL', re.compile(r'\bNETT\s+TOTAL\b')),
    ('NET TOTAL', re.compile(r'\bNET\s+TOTAL\b')),
    ('TOTAL:', re.compile(r'\bTOTAL\s*:\b')),
    ('TOTAL', re.compile(r'\bTOTAL\b')),
