IMG_DIR = Path('/app/workspace/dataset/img')
OUT_XLSX = Path('/app/workspace/stat_ocr.xlsx')

IMAGE_EXTS = {'.jpg', '.jpeg', '.png', '.webp', '.tif', '.tiff', '.bmp'}

HARD_EXCLUDE = [
    'SUBTOTAL',
    'SUB TOTAL',
    'DISCOUNT',
    'CHANGE',
    'CASH TENDERED',
    'GST SUMMARY',
]

TAX_WORDS = ['TAX', 'GST', 'SST']

ALLOW_TOTAL_CONTEXT = [
    'GRAND TOTAL',
    'TOTAL RM',
    'TOTAL: RM',
    'TOTAL:',
    'TOTAL AMOUNT',
    'TOTAL DUE',
    'AMOUNT DUE',
    'BALANCE DUE',
    'NETT TOTAL',
    'NET TOTAL',
    'TOTAL ROUNDED',
    'TOTAL SALES',
    'TOTAL (RM)',
]

HEADER_EXCLUDE_SUBSTRS = [
    'DESCRIPTION AMOUNT',
    'DESCRIPTION  AMOUNT',
    'DESCRIPTION AMOUNT TX',
    'AMOUNT TX',
    'QTY ITEM TOTAL',
]

KEYWORD_GROUPS = [
    ['GRAND TOTAL'],
    ['TOTAL:', 'TOTAL RM', 'TOTAL: RM', 'TOTAL ROUNDED', 'TOTAL SALES'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'NETT', 'NET'],
]

# Money token patterns
DOT_DECIMAL_RE = re.compile(r"(?<!\d)(?:\d{1,3}(?:,\d{3})+|\d+)\.\d{1,2}(?!\d)")
COMMA_DECIMAL_RE = re.compile(r"(?<!\d)(?:\d{1,3}(?:,\d{3})+|\d+),(?:\d{1,2})(?!\d)")
INTEGER_RE = re.compile(r"(?<!\d)(?:\d{1,3}(?:,\d{3})+|\d+)(?!\d)")

# Date patterns (include 2-digit years)
DATE_PATTERNS = [
    re.compile(r"(?P<y>\d{4})[\-\./](?P<m>\d{1,2})[\-\./](?P<d>\d{1,2})"),
    re.compile(r"(?P<a>\d{1,2})[\-\./](?P<b>\d{1,2})[\-\./](?P<y>\d{4})"),
    re.compile(r"(?P<a>\d{1,2})[\-\./](?P<b>\d{1,2})[\-\./](?P<y2>\d{2})"),
    re.compile(r"(?P<d>\d{1,2})\s*[\-\./]?\s*(?P<mon>JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*\s*[\-\./,]?\s*(?P<y>\d{4})"),
    re.compile(r"(?P<mon>JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*\s*[\-\./]?\s*(?P<d>\d{1,2})\s*[\-\./,]?\s*(?P<y>\d{4})"),
]

MONTH_MAP = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'SEPT': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12,
}


def preprocess_variants(img):
    gray = ImageOps.grayscale(img)
    v1 = ImageOps.autocontrast(gray)
    v2 = v1.filter(ImageFilter.SHARPEN)
    v3 = v1.point(lambda p: 255 if p > 170 else 0)
    return [v1, v2, v3]


def ocr_lines(img_path: Path) -> list[str]:
    img = Image.open(img_path)
    texts: list[str] = []

    for v in preprocess_variants(img):
        for psm in (3, 4, 6, 11):
            try:
                t = pytesseract.image_to_string(v, config=f'--psm {psm}')
            except Exception:
                continue
            if t and t.strip():
                texts.append(t)

    seen = set()
    out: list[str] = []
    for t in texts:
        for line in t.splitlines():
            s = re.sub(r"\s+", " ", line).strip()
            if not s:
                continue
            key = s.upper()
            if key in seen:
                continue
            seen.add(key)
            out.append(s)
    return out


def normalize_numbers(s: str) -> str:
    # Join separated decimals: "85. 54" -> "85.54", "99, 80" -> "99,80"
    s = re.sub(r"(\d)\s*\.\s*(\d)", r"\1.\2", s)
    s = re.sub(r"(\d)\s*,\s*(\d)", r"\1,\2", s)
    return s


def parse_money_token(tok: str) -> Decimal | None:
    tok = tok.strip()
    if not tok:
        return None

    if '.' in tok and ',' in tok:
        cleaned = tok.replace(',', '')
    elif ',' in tok and '.' not in tok:
        if tok.count(',') == 1 and re.search(r",\d{1,2}$", tok):
            cleaned = tok.replace(',', '.')
        else:
            cleaned = tok.replace(',', '')
    else:
        cleaned = tok

    try:
        d = Decimal(cleaned)
    except (InvalidOperation, ValueError):
        return None

    if d <= 0 or d >= Decimal('1000000'):
        return None

    return d


def fmt_2dp(d: Decimal) -> str:
    d2 = d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return f"{d2:.2f}"


def is_excluded_for_total(up: str) -> bool:
    if any(k in up for k in HARD_EXCLUDE):
        return True
    if any(h in up for h in HEADER_EXCLUDE_SUBSTRS):
        return True

    if any(t in up for t in TAX_WORDS):
        # Allow tax words on lines that clearly represent totals
        if any(a in up for a in ALLOW_TOTAL_CONTEXT):
            return False
        if 'TOTAL' in up:
            return False
        return True

    return False


def best_amount_in_line(line: str, allow_integer_fallback: bool) -> str | None:
    line = normalize_numbers(line)

    # Prefer decimal-like tokens; take last on the line.
    dec_tokens = DOT_DECIMAL_RE.findall(line) + COMMA_DECIMAL_RE.findall(line)
    if dec_tokens:
        for tok in reversed(dec_tokens):
            d = parse_money_token(tok)
            if d is not None:
                return fmt_2dp(d)

    if not allow_integer_fallback:
        return None

    # Integer fallback: choose the maximum plausible integer token.
    vals = []
    for tok in INTEGER_RE.findall(line):
        d = parse_money_token(tok)
        if d is None:
            continue
        vals.append(d)
    if not vals:
        return None
    return fmt_2dp(max(vals))


def extract_total_amount(lines: list[str]) -> str | None:
    ups = [ln.upper() for ln in lines]

    for group in KEYWORD_GROUPS:
        found: str | None = None
        for i, (ln, up) in enumerate(zip(lines, ups)):
            if is_excluded_for_total(up):
                continue
            if not any(k in up for k in group):
                continue

            strong = any(k in up for k in ('GRAND TOTAL', 'TOTAL:', 'TOTAL RM', 'TOTAL: RM', 'TOTAL AMOUNT', 'TOTAL DUE', 'NET TOTAL', 'NETT TOTAL', 'TOTAL ROUNDED', 'TOTAL SALES'))

            val = best_amount_in_line(ln, allow_integer_fallback=strong)
            if val is None and i + 1 < len(lines):
                nxt_up = ups[i + 1]
                if not is_excluded_for_total(nxt_up):
                    val = best_amount_in_line(lines[i + 1], allow_integer_fallback=strong)

            if val is not None:
                found = val  # keep last match within this group

        if found is not None:
            return found

    return None


def parse_date_match(m: re.Match) -> datetime | None:
    gd = m.groupdict()
    try:
        if gd.get('y') and gd.get('m') and gd.get('d'):
            return datetime(int(gd['y']), int(gd['m']), int(gd['d']))

        if gd.get('a') and gd.get('b') and gd.get('y'):
            a = int(gd['a']); b = int(gd['b']); y = int(gd['y'])
            if a > 12 and 1 <= b <= 12:
                d, mo = a, b
            elif b > 12 and 1 <= a <= 12:
                mo, d = a, b
            else:
                d, mo = a, b
            return datetime(y, mo, d)

        if gd.get('a') and gd.get('b') and gd.get('y2'):
            a = int(gd['a']); b = int(gd['b']); y2 = int(gd['y2'])
            y = 2000 + y2 if y2 <= 69 else 1900 + y2
            if a > 12 and 1 <= b <= 12:
                d, mo = a, b
            elif b > 12 and 1 <= a <= 12:
                mo, d = a, b
            else:
                d, mo = a, b
            return datetime(y, mo, d)

        if gd.get('mon') and gd.get('y') and gd.get('d'):
            mon_key = gd['mon'].upper()
            mo = MONTH_MAP.get(mon_key[:4], MONTH_MAP.get(mon_key[:3]))
            if mo is None:
                return None
            return datetime(int(gd['y']), int(mo), int(gd['d']))

    except ValueError:
        return None

    return None


def extract_date(lines: list[str]) -> str | None:
    for ln in lines:
        up = ln.upper()
        up2 = re.sub(r"\b(\d{1,2}:\d{2}(:\d{2})?)\b", " ", up)
        for pat in DATE_PATTERNS:
            m = pat.search(up2)
            if not m:
                continue
            dt = parse_date_match(m)
            if dt:
                return dt.strftime('%Y-%m-%d')
    return None


def main():
    img_files = sorted([p for p in IMG_DIR.iterdir() if p.is_file() and p.suffix.lower() in IMAGE_EXTS], key=lambda p: p.name)

    rows: list[tuple[str, str | None, str | None]] = []
    for p in img_files:
        lines = ocr_lines(p)
        date_iso = extract_date(lines)
        total = extract_total_amount(lines)
        rows.append((p.name, date_iso, total))

    OUT_XLSX.parent.mkdir(parents=True, exist_ok=True)
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'

    ws.cell(row=1, column=1, value='filename')
    ws.cell(row=1, column=2, value='date')
    ws.cell(row=1, column=3, value='total_amount')

    for r_idx, (fn, dt, amt) in enumerate(rows, start=2):
        ws.cell(row=r_idx, column=1, value=fn)
        ws.cell(row=r_idx, column=2, value=dt)
        ws.cell(row=r_idx, column=3, value=amt)

    wb.save(OUT_XLSX)

    # Validate output contract
    wb2 = load_workbook(OUT_XLSX)
    assert wb2.sheetnames == ['results'], wb2.sheetnames
    ws2 = wb2['results']
    assert [ws2.cell(row=1, column=i).value for i in (1,2,3)] == ['filename','date','total_amount']

    fns = [ws2.cell(row=r, column=1).value for r in range(2, 2 + len(rows))]
    assert fns == sorted(fns)

    return rows


if __name__ == '__main__':
    rows = main()
    for r in rows:
        print(r)
