        if gd.get('a') and gd.get('b') and gd.get('y'):
            a = int(gd['a']); b = int(gd['b']); y = int(gd['y'])
            if a > 12 and 1 <= b <= 12:
                d, mo = a, b
            elif b > 12 and 1 <= a <= 12:
                mo, d = a, b
            else:
                d, mo = a, b
            return datetime(y, mo, d)
