import re
from pathlib import Path
from datetime import datetime
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

import pandas as pd
from PIL import Image, ImageOps, ImageFilter
import pytesseract

IMG_DIR = Path('/app/workspace/dataset/img')
OUT_XLSX = Path('/app/workspace/stat_ocr.xlsx')

IMAGE_EXTS = {'.jpg', '.jpeg', '.png', '.webp', '.tif', '.tiff', '.bmp'}

EXCLUSIONS = [
    'SUBTOTAL',
    'SUB TOTAL',
    'TAX',
    'GST',
    'SST',
    'DISCOUNT',
    'CHANGE',
    'CASH TENDERED',
]

# Priority keyword groups (highest first)
KEYWORD_GROUPS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
]

MONEY_RE = re.compile(r"(?<!\d)(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d{1,2})?(?!\d)")

DATE_PATTERNS = [
    # 2023-08-12, 2023/08/12, 2023.08.12
    re.compile(r"(?P<y>\d{4})[\-\./](?P<m>\d{1,2})[\-\./](?P<d>\d{1,2})"),
    # 12-08-2023, 12/08/2023
    re.compile(r"(?P<a>\d{1,2})[\-\./](?P<b>\d{1,2})[\-\./](?P<y>\d{4})"),
    # 12 Aug 2023, 12-Aug-2023
    re.compile(r"(?P<d>\d{1,2})\s*[\-\./]?\s*(?P<mon>JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*\s*[\-\./,]?\s*(?P<y>\d{4})"),
    # Aug 12 2023, Aug-12-2023
    re.compile(r"(?P<mon>JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*\s*[\-\./]?\s*(?P<d>\d{1,2})\s*[\-\./,]?\s*(?P<y>\d{4})"),
]

MONTH_MAP = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'SEPT': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12,
}


def preprocess_variants(img: Image.Image):
    # Lightweight multi-pass preprocessing to improve OCR on scans.
    gray = ImageOps.grayscale(img)
    v1 = ImageOps.autocontrast(gray)
    v2 = v1.filter(ImageFilter.SHARPEN)
    # binary threshold
    v3 = v1.point(lambda p: 255 if p > 170 else 0)
    return [v1, v2, v3]


def ocr_text(img_path: Path) -> str:
    img = Image.open(img_path)
    variants = preprocess_variants(img)
    texts = []
    for v in variants:
        for psm in (6, 11):
            try:
                t = pytesseract.image_to_string(v, config=f'--psm {psm}')
                if t and t.strip():
                    texts.append(t)
            except Exception:
                pass
    # Combine, de-duplicate lines while preserving order
    seen = set()
    out_lines = []
    for t in texts:
        for line in t.splitlines():
            s = re.sub(r"\s+", " ", line).strip()
            if not s:
                continue
            key = s.upper()
            if key in seen:
                continue
            seen.add(key)
            out_lines.append(s)
    return "\n".join(out_lines)


