from __future__ import annotations

import re
from pathlib import Path
from datetime import datetime
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

import pandas as pd
from PIL import Image, ImageOps, ImageFilter
import pytesseract

IMG_DIR = Path('/app/workspace/dataset/img')
OUT_XLSX = Path('/app/workspace/stat_ocr.xlsx')

IMAGE_EXTS = {'.jpg', '.jpeg', '.png', '.webp', '.tif', '.tiff', '.bmp'}

EXCLUSIONS = [
    'SUBTOTAL',
    'SUB TOTAL',
    'TAX',
    'GST',
    'SST',
    'DISCOUNT',
    'CHANGE',
    'CASH TENDERED',
]

# Priority keyword groups (highest first)
KEYWORD_GROUPS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
]

MONEY_RE = re.compile(r"(?<!\d)(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d{1,2})?(?!\d)")

DATE_PATTERNS = [
    # 2023-08-12, 2023/08/12, 2023.08.12
    re.compile(r"(?P<y>\d{4})[\-\./](?P<m>\d{1,2})[\-\./](?P<d>\d{1,2})"),
    # 12-08-2023, 12/08/2023
    re.compile(r"(?P<a>\d{1,2})[\-\./](?P<b>\d{1,2})[\-\./](?P<y>\d{4})"),
    # 12 Aug 2023, 12-Aug-2023
    re.compile(r"(?P<d>\d{1,2})\s*[\-\./]?\s*(?P<mon>JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*\s*[\-\./,]?\s*(?P<y>\d{4})"),
    # Aug 12 2023, Aug-12-2023
    re.compile(r"(?P<mon>JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*\s*[\-\./]?\s*(?P<d>\d{1,2})\s*[\-\./,]?\s*(?P<y>\d{4})"),
]

MONTH_MAP = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'SEPT': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12,
}


def preprocess_variants(img: Image.Image):
    # Lightweight multi-pass preprocessing to improve OCR on scans.
    gray = ImageOps.grayscale(img)
    v1 = ImageOps.autocontrast(gray)
    v2 = v1.filter(ImageFilter.SHARPEN)
    # binary threshold
    v3 = v1.point(lambda p: 255 if p > 170 else 0)
    return [v1, v2, v3]


def ocr_text(img_path: Path) -> str:
    img = Image.open(img_path)
    variants = preprocess_variants(img)
    texts = []
    for v in variants:
        for psm in (6, 11):
            try:
                t = pytesseract.image_to_string(v, config=f'--psm {psm}')
                if t and t.strip():
                    texts.append(t)
            except Exception:
                pass
    # Combine, de-duplicate lines while preserving order
    seen = set()
    out_lines = []
    for t in texts:
        for line in t.splitlines():
            s = re.sub(r"\s+", " ", line).strip()
            if not s:
                continue
            key = s.upper()
            if key in seen:
                continue
            seen.add(key)
            out_lines.append(s)
    return "\n".join(out_lines)


def is_excluded(line_up: str) -> bool:
    return any(k in line_up for k in EXCLUSIONS)


def extract_money_candidates(s: str):
    # return all number-like candidates; caller chooses last typically
    return MONEY_RE.findall(s)


def money_to_2dp(m: str) -> str | None:
    try:
        d = Decimal(m.replace(',', ''))
    except (InvalidOperation, AttributeError):
        return None
    d = d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    # Ensure exactly two decimals
    return f"{d:.2f}"


def extract_total_amount(lines: list[str]) -> str | None:
    # Keyword-driven extraction (priority groups)
    lines_up = [re.sub(r"\s+", " ", ln).strip().upper() for ln in lines]

    for group in KEYWORD_GROUPS:
        for i, (ln, up) in enumerate(zip(lines, lines_up)):
            if is_excluded(up):
                continue
            if not any(k in up for k in group):
                continue

            nums = extract_money_candidates(ln)
            if nums:
                val = money_to_2dp(nums[-1])
                if val is not None:
                    return val

            # Fallback: keyword line then amount on next line
            if i + 1 < len(lines):
                nxt = lines[i + 1]
                nxt_up = lines_up[i + 1]
                if not is_excluded(nxt_up):
                    nums2 = extract_money_candidates(nxt)
                    if nums2:
                        val = money_to_2dp(nums2[-1])
                        if val is not None:
                            return val

    # Final fallback: scan bottom-up for a plausible total-like line
    totalish = ['TOTAL', 'AMOUNT', 'DUE', 'BALANCE', 'NETT', 'NET', 'GRAND']
    for ln, up in zip(reversed(lines), reversed(lines_up)):
        if is_excluded(up):
            continue
        if not any(k in up for k in totalish):
            continue
        nums = extract_money_candidates(ln)
        if nums:
            val = money_to_2dp(nums[-1])
            if val is not None:
                return val
    return None


def parse_date_match(m: re.Match) -> datetime | None:
    gd = m.groupdict()
    try:
        if 'm' in gd and 'd' in gd and 'y' in gd and gd.get('m') and gd.get('d'):
            y = int(gd['y']); mo = int(gd['m']); d = int(gd['d'])
            return datetime(y, mo, d)
        if 'a' in gd and 'b' in gd and 'y' in gd:
            a = int(gd['a']); b = int(gd['b']); y = int(gd['y'])
            # Heuristic: prefer DD/MM/YYYY when ambiguous
            if a > 12 and 1 <= b <= 12:
                d, mo = a, b
            elif b > 12 and 1 <= a <= 12:
                mo, d = a, b
            else:
                d, mo = a, b
            return datetime(y, mo, d)
        if 'mon' in gd and 'y' in gd and 'd' in gd:
            y = int(gd['y']); d = int(gd['d']); mo = MONTH_MAP.get(gd['mon'][:4].upper().replace('T','T'), None)
            if mo is None:
                mo = MONTH_MAP.get(gd['mon'][:3].upper())
            if mo is None:
                return None
            return datetime(y, mo, d)
    except ValueError:
        return None
    return None


def extract_date(lines: list[str]) -> str | None:
    for ln in lines:
        up = ln.upper()
        # Strip obvious time suffixes to help matching
        up2 = re.sub(r"\b(\d{1,2}:\d{2}(:\d{2})?)\b", " ", up)
        for pat in DATE_PATTERNS:
            m = pat.search(up2)
            if not m:
                continue
            dt = parse_date_match(m)
            if dt:
                return dt.strftime('%Y-%m-%d')
    return None


img_files = sorted([p for p in IMG_DIR.iterdir() if p.is_file() and p.suffix.lower() in IMAGE_EXTS], key=lambda p: p.name)

rows = []
for p in img_files:
    text = ocr_text(p)
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]

    date_iso = extract_date(lines)
    total = extract_total_amount(lines)

    rows.append({
        'filename': p.name,
        'date': date_iso,
        'total_amount': total,
    })

# Write workbook with strict schema
OUT_XLSX.parent.mkdir(parents=True, exist_ok=True)
df = pd.DataFrame(rows, columns=['filename', 'date', 'total_amount'])
df.to_excel(OUT_XLSX, index=False, sheet_name='results')

# Validate deliverable contract
from openpyxl import load_workbook
wb = load_workbook(OUT_XLSX)
assert wb.sheetnames == ['results'], wb.sheetnames
ws = wb['results']
headers = [c.value for c in next(ws.iter_rows(min_row=1, max_row=1))]
assert headers == ['filename', 'date', 'total_amount'], headers

# Ensure rows are ordered by filename
check = pd.read_excel(OUT_XLSX, sheet_name='results', dtype={'filename': str, 'date': object, 'total_amount': object})
assert list(check.columns) == ['filename', 'date', 'total_amount']
assert list(check['filename']) == sorted(check['filename'].tolist())

print(f"Wrote {OUT_XLSX} with {len(df)} rows")
print(df.head(10).to_string(index=False))
PY", "summary": "OCR receipts, parse date and total, write stat_ocr.xlsx", "security_risk": "MEDIUM", "timeout": 300}

