    ('GRAND TOTAL', re.compile(r'\bGRAND\s+TOTAL\b')),
    ('TOTAL: RM', re.compile(r'\bTOTAL\s*:\s*RM\b')),
    ('TOTAL RM', re.compile(r'\bTOTAL\s*RM\b')),
