COMMA_DEC_RE = re.compile(r'(?<!\d)(?:\d{1,3}(?:,\d{3})+|\d+),(?:\d{1,2})(?!\d)')
INTEGER_RE = re.compile(r'(?<!\d)(?:\d{1,3}(?:,\d{3})+|\d+)(?!\d)')

