def preprocess_variants(img):
    gray = ImageOps.grayscale(img)
    v1 = ImageOps.autocontrast(gray)
    v2 = v1.filter(ImageFilter.SHARPEN)
    v3 = v1.point(lambda p: 255 if p > 170 else 0)
    return [v1, v2, v3]
def ocr_lines(img_path: Path) -> list[str]:
    img = Image.open(img_path)
    out: list[str] = []
    for v in preprocess_variants(img):
        for psm in (3, 4, 6, 11):
            try:
                t = pytesseract.image_to_string(v, config=f'--psm {psm}')
            except Exception:
                continue
            for line in t.splitlines():
                s = re.sub(r'\s+', ' ', line).strip()
                if s:
                    out.append(s)
    return out
def normalize_numbers(s: str) -> str:
    s = re.sub(r'(\d)\s*\.\s*(\d)', r'\1.\2', s)
    s = re.sub(r'(\d)\s*,\s*(\d)', r'\1,\2', s)
    return s
def parse_money_token(tok: str) -> Decimal | None:
    tok = tok.strip()
    if not tok:
        return None
    if '.' in tok and ',' in tok:
        cleaned = tok.replace(',', '')
    elif ',' in tok and '.' not in tok:
        if tok.count(',') == 1 and re.search(r',\d{1,2}$', tok):
            cleaned = tok.replace(',', '.')
        else:
            cleaned = tok.replace(',', '')
    else:
        cleaned = tok
    try:
        d = Decimal(cleaned)
    except (InvalidOperation, ValueError):
        return None
    if d <= 0 or d >= Decimal('1000000'):
        return None
    return d
def fmt_2dp(d: Decimal) -> str:
    q = d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return f'{q:.2f}'
def excluded_line(up: str) -> bool:
    if any(k in up for k in EXCLUDE_ALWAYS):
        return True
    if any(k in up for k in HEADER_EXCLUDE):
        return True
    # Exclude tax-only lines unless they contain total context.
    if any(t in up for t in TAX_WORDS) and 'TOTAL' not in up:
        return True
    # Exclude "TAX TOTAL" lines so we don't pick GST amounts.
    if 'TAX' in up and 'TOTAL' in up and 'GRAND' not in up and 'TOTAL RM' not in up and '(RM' not in up:
        return True
    return False
def amount_from_line(line: str, allow_int_fallback: bool) -> tuple[str | None, bool]:
    line = normalize_numbers(line)
    decs = DOT_DEC_RE.findall(line) + COMMA_DEC_RE.findall(line)
    if decs:
        for tok in reversed(decs):
            d = parse_money_token(tok)
            if d is not None:
                return fmt_2dp(d), True
    if not allow_int_fallback:
        return None, False
    vals: list[Decimal] = []
    for tok in INTEGER_RE.findall(line):
        d = parse_money_token(tok)
        if d is not None:
            vals.append(d)
    if not vals:
        return None, False
    return fmt_2dp(max(vals)), False
def compute_total_from_cash_change(lines: list[str]) -> str | None:
    cash = None
    change = None
    for ln in lines:
        up = ln.upper()
        if cash is None and 'CASH RECEIVED' in up:
            val, _ = amount_from_line(ln, allow_int_fallback=False)
            if val:
                cash = Decimal(val)
        if change is None and up.strip().startswith('CHANGE'):
            val, _ = amount_from_line(ln, allow_int_fallback=False)
            if val:
                change = Decimal(val)
    if cash is None or change is None:
        return None
    total = cash - change
    if total <= 0:
        return None
    return fmt_2dp(total)
def extract_total_amount(lines: list[str]) -> str | None:
    ups = [ln.upper() for ln in lines]
    for _name, pat in KEYWORD_PATTERNS:
        counts: dict[str, int] = {}
        last_idx: dict[str, int] = {}
        used_decimal: dict[str, bool] = {}
        for i, (ln, up) in enumerate(zip(lines, ups)):
            if excluded_line(up):
                continue
            if not pat.search(up):
                continue
            strong = bool(STRONG_TOTAL_CONTEXT.search(up))
            val, dec = amount_from_line(ln, allow_int_fallback=strong)
            if val is None and strong and i + 1 < len(lines) and not excluded_line(ups[i + 1]):
                val, dec = amount_from_line(lines[i + 1], allow_int_fallback=strong)
            if val is None:
                continue
            counts[val] = counts.get(val, 0) + 1
            last_idx[val] = i
            used_decimal[val] = used_decimal.get(val, False) or dec
        if counts:
            best_count = max(counts.values())
            cands = [v for v, c in counts.items() if c == best_count]
            best = max(cands, key=lambda v: last_idx.get(v, -1))
            computed = compute_total_from_cash_change(lines)
            if computed and (not used_decimal.get(best, True)):
                return computed
            return best
    return compute_total_from_cash_change(lines)
def parse_date_match(m: re.Match) -> datetime | None:
    gd = m.groupdict()
    try:
        if gd.get('y') and gd.get('m') and gd.get('d'):
            return datetime(int(gd['y']), int(gd['m']), int(gd['d']))
        if gd.get('a') and gd.get('b') and gd.get('y'):
            a = int(gd['a']); b = int(gd['b']); y = int(gd['y'])
            if a > 12 and 1 <= b <= 12:
                d, mo = a, b
            elif b > 12 and 1 <= a <= 12:
                mo, d = a, b
            else:
                d, mo = a, b
            return datetime(y, mo, d)
        if gd.get('a') and gd.get('b') and gd.get('y2'):
            a = int(gd['a']); b = int(gd['b']); y2 = int(gd['y2'])
            y = 2000 + y2 if y2 <= 69 else 1900 + y2
            if a > 12 and 1 <= b <= 12:
                d, mo = a, b
            elif b > 12 and 1 <= a <= 12:
                mo, d = a, b
            else:
                d, mo = a, b
            return datetime(y, mo, d)
        if gd.get('mon') and gd.get('y') and gd.get('d'):
            mon = gd['mon'].upper()
            mo = MONTH_MAP.get(mon[:4], MONTH_MAP.get(mon[:3]))
            if mo is None:
                return None
            return datetime(int(gd['y']), int(mo), int(gd['d']))
    except ValueError:
        return None
    return None
def extract_date(lines: list[str]) -> str | None:
    def collect(pats):
        counts: dict[str, int] = {}
        first_idx: dict[str, int] = {}
        for i, ln in enumerate(lines):
            up = ln.upper()
            up2 = re.sub(r'\b(\d{1,2}:\d{2}(:\d{2})?)\b', ' ', up)
            for pat in pats:
                m = pat.search(up2)
                if not m:
                    continue
                dt = parse_date_match(m)
                if not dt:
                    continue
                iso = dt.strftime('%Y-%m-%d')
                counts[iso] = counts.get(iso, 0) + 1
                first_idx.setdefault(iso, i)
        return counts, first_idx
    c4, idx4 = collect(DATE_PATTERNS_4)
    if c4:
        best_count = max(c4.values())
        cands = [d for d, c in c4.items() if c == best_count]
        return min(cands, key=lambda d: idx4.get(d, 10**9))
    c2, idx2 = collect(DATE_PATTERNS_2)
    if not c2:
        return None
    best_count = max(c2.values())
    cands = [d for d, c in c2.items() if c == best_count]
    return min(cands, key=lambda d: idx2.get(d, 10**9))
